```python
def solve(n):
    """
    Find 3 distinct positive integer x, y, z not divisible by 3 
    such that their sum is n.

    Parameters:
    ----------
    n : int
        The target sum of three integers

    Returns:
    -------
    str
        YES followed by the numbers or NO if no valid triplet exists
    """

    # check for special case where smallest possible n is given 
    if (n < 7) or ((n == 9)):  
        return "NO"

    # if remainder of n/3 equals one, add two and divide to find an approximate average
    elif (n % 3 == 1):
        avg = round(((((n+2)/3)-1)))

        num_list = []
        for x in range(0+1,avg + 1):
            y = round(avg-x)
            z = n -x-y
            if not(((x > 0) and (y > x) and (z > y)) 
                   and ((x != -1) or (y != 2))) == False:
                num_list = [str(x), str(y), str(z)]
        return 'YES\n' + ' '.join(num_list)

    # if remainder of n/3 equals two, subtract one and divide to find an approximate average
    elif (n % 3 == 2):
        avg = round(((n-1)/3))

        num_list = []
        for x in range(0+1, avg + 1):
            y = round(avg-x)
            z = n -x-y 
            if not(((x > 0) and (y > x) and (z > y)) 
                   and ((x != -1 or y != 2))) == False:
                num_list = [str(x), str(y), str(z)]
        return 'YES\n' + ' '.join(num_list)

    else:       
        # otherwise case is where n/3 remainder equals zero.
        avg = round(((((n)/3)-1)))

        for x in range (0+1,avg + 1): 
            y = round(avg-x)
            z = round(n -x-y)  
            if ((z != 0)and(z%2 ==0))or(x %3== 0) or(y%3==0):
                continue
            else:
                return 'YES\n' + str(x) + " "+str( y)+" "+str(z)

