    A = list(map(int, input().split()))
    max_heap, min_heap = [], []

    for num in A:
        if len(max_heap) < 2: heapq.heappush(max_heap, -num)
        elif max_heap[0] < -num: 
            heapq.heapreplace(max_heap, -num)

        if len(min_heap) < 2: heapq.heappush(min_heap, num)
        elif min_heap[0] > num: 
