def solve():
    a, b = map(int, input().split())
    n, m = map(int, input().split())

    free_potatoes = (n // (m + 1)) * (m + 1 if m < n else n)
    payed_potatoes_m = (n - free_potatoes) // m
    left_kg = n - free_potatoes - payed_potatoes_m * m

    cost = min(a, b) * free_potatoes + a * payed_potatoes_m * m + min(a,b) * left_kg
    if (a / (m + 1 <= 0 or a >= b)):
        return int(min(cost, n * b))
    else:
        with_free_potatoes = ((n // (m + 1)) * m * (a/(m+1))) + min(a, b) * (n -((n // (m + 1))  * (m +1)))
        return int(min(with_free_potatoes, n * b))
