    n = int(input())
    s = input()

    def invert(s):
        for x in '0101', '1010':
            s = re.sub('(' + '|'.join([x[i:] + '.' * (2-i) for i in [0, 1]]) + ')', lambda m: {'00': '11', '01': '10', '10': '01', '11': '00'}[m.group()[:2]], s)
