        return s == s[::-1]

    def solve(s, invert_func, palindrome_func):
        for x in ['00', '01', '10', '11']:
            a = re.sub('^' + x + '+|' + x + '+$', '', s)
            if not a:
                continue
            m = re.match('(' + '|'.join([x[i:] + '.' * (2-i) for i in [0, 1]]) + ')', a[::-1])
            if len(a) < 3 or m and len(m.group()) == 1:
                return palindrome_func(invert_func(s))
        return False

    print('Yes' if solve(s, invert, is_palindrome) else 'No')
